import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    return <div className="dsscorebar-example">
    <style>{exampleStyles}</style>
    <S.DsScoreBar value={78} label={'Эко-вождение'} unit={'баллов'}/>
    </div>;
}

const exampleStyles = ".dsscorebar-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsscorebar-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsscorebar-example p{margin:0}\n";

export { App as Example };

